52	        } else if (column_schema->is_shadow_column()) {
53	          // do nothing
54	        } else {
55	          ColumnPair pair(i, column_schema->get_column_name_str());
56	          pair.col_id_ = column_id;
57	          if ((is_index_table && column_schema->is_index_column()) ||
58	              (!is_index_table && column_schema->is_rowkey_column())) {
