62	                                                  : column_schema->get_rowkey_position();
63	          }
64	          if (OB_FAIL(column_pairs_.push_back(pair))) {
65	            LOG_WARN("fail to push back", KR(ret), K(i), "column_name", column_schema->get_column_name_str());
66	          }
67	        }
68	      }
69	    }
70	  }
