250	int ObTableTTLDeleteTask::process()
251	{
252	  int ret = OB_SUCCESS;
253	  info_.start_time_ = ObTimeUtility::current_time();
254	  if (IS_NOT_INIT) {
255	    ret = OB_NOT_INIT;
256	    LOG_WARN("not init", K(ret));
257	  } else if (OB_FAIL(delete_rate_throttler_.init(info_))) {
258	    LOG_WARN("fail to init delete rate throttler", KR(ret), K(delete_rate_throttler_));
259	  } else {
260	    bool need_stop = false;
261	    // pre-check to quick cancel/suspend current task in case of tenant ttl state changed
262	    // since it maybe wait in dag queue for too long
263	    if (OB_FAIL(ttl_tablet_scheduler_->report_task_status(info_, param_, need_stop, false))) {
264	      LOG_WARN("fail to report ttl task status", KR(ret));
265	    }
266	    // explicit cover retcode
267	    while(!need_stop) {
268	      lib::ContextParam param;
269	      param.set_mem_attr(MTL_ID(), "TTLDeleteMemCtx", ObCtxIds::DEFAULT_CTX_ID)
270	        .set_properties(lib::USE_TL_PAGE_OPTIONAL);
271	      CREATE_WITH_TEMP_CONTEXT(param) {
272	        if (OB_FAIL(process_one())) {
273	          if (OB_ITER_END != ret) {
274	            LOG_WARN("fail to process one", KR(ret));
275	          }
276	        }
277	        // explicit cover retcode
278	        if (OB_FAIL(ttl_tablet_scheduler_->report_task_status(info_, param_, need_stop))) {
279	          LOG_WARN("fail to report ttl task status", KR(ret));
280	        }
281	        allocator_.reuse();
282	      }
283	    }
284	  }
285	  ttl_tablet_scheduler_->dec_dag_ref();
286	  return ret;
287	}
